def analyze(grid):
    h,w=len(grid),len(grid[0]); seen=set(); q=deque()
    for i in range(h):
        for j in (0,w-1):
            if grid[i][j]==9 and (i,j) not in seen: q.append((i,j)); seen.add((i,j))
    for j in range(w):
        for i in (0,h-1):
            if grid[i][j]==9 and (i,j) not in seen: q.append((i,j)); seen.add((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and grid[ni][nj]==9 and (ni,nj) not in seen:
                q.append((ni,nj)); seen.add((ni,nj))
    return seen
