def flood(inp,val,fill):
    h,w=len(inp),len(inp[0]); seen=[[False]*w for _ in range(h)]; q=deque()
    for i in range(h):
        for j in range(w):
            if (i==0 or i==h-1 or j==0 or j==w-1) and inp[i][j]!=val and not seen[i][j]:
                seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and inp[ni][nj]==val and not seen[ni][nj]:
                seen[ni][nj]=True; q.append((ni,nj))
    return [[fill if inp[i][j]==val and not seen[i][j] else inp[i][j] for j in range(w)] for i in range(h)]
